const results = [];
document.querySelectorAll('a[id*="mntl-card-list-card"]').forEach(card => {
  const titleEl = card.querySelector('span');
  const ratingTextEl = card.querySelector('[id*="mntl-recipe-card-meta"] div div');
  const ratingCount = card.querySelector('[id*="mntl-recipe-star-rating"]')?.parentElement?.nextElementSibling?.textContent;
  const ratingImg = card.querySelectorAll('svg');
  results.push({
    title: titleEl?.textContent?.trim(),
    ratingEl: ratingTextEl?.textContent?.trim(),
    ratingCount: ratingCount,
    fullCardText: card.textContent.trim().substring(0, 300)
  });
});
return results;

const data = [];
document.querySelectorAll('a[id*="mntl-card-list-card"]').forEach(card => {
  const title = card.querySelector('span')?.textContent?.trim();
  // Get rating container with the actual rating text
  const allDivs = card.querySelectorAll('div');
  let rating = '';
  let reviewCount = '';
  allDivs.forEach(div => {
    const txt = div.textContent.trim();
    if (/^\d\.\d$/.test(txt) && !rating) rating = txt;
    if (txt.includes('Reviews') && !reviewCount) reviewCount = txt;
  });
  data.push({title, rating, reviewCount});
});
return data;

const ratingEls = document.querySelectorAll('[id*="mntl-recipe-star-rating"]');
const result = [];
ratingEls.forEach(el => {
  result.push({
    id: el.id,
    ariaLabel: el.getAttribute('aria-label'),
    title: el.getAttribute('title'),
    innerHTML: el.innerHTML.substring(0, 500),
    outerHTML: el.outerHTML.substring(0, 1000)
  });
});
return result.slice(0, 3);

const results = [];
document.querySelectorAll('a[id*="mntl-card-list-card"]').forEach(card => {
  const title = card.querySelector('span')?.textContent?.trim();
  const ratingEl = card.querySelector('[id*="mntl-recipe-star-rating"]');
  let rating = 0;
  if (ratingEl) {
    const fullStars = ratingEl.querySelectorAll('svg.icon-star').length;
    const halfStars = ratingEl.querySelectorAll('svg.icon-star-half').length;
    const emptyStars = ratingEl.querySelectorAll('svg.icon-star-empty').length;
    // Use SVG count: full + half = (e.g. 4 full + 1 half = 4.5)
    rating = fullStars + (halfStars * 0.5);
  }
  const ratingCountEl = ratingEl?.parentElement?.querySelector('div[class*="rating-count"]') || card.querySelector('[id*="mntl-recipe-card-meta"] > div:last-child');
  const ratingCount = ratingCountEl?.textContent?.trim();
  // Get reviews from the full text
  const allText = card.textContent;
  const reviewMatch = allText.match(/(\d+)\s*Reviews?/);
  const ratingsMatch = allText.match(/(\d+)\s*Ratings?/);
  results.push({title, rating, ratingsCount: ratingsMatch?.[1], reviewsCount: reviewMatch?.[1]});
});
return results;

const ingredients = [];
document.querySelectorAll('li[data-ingredient-name], ul.mm-recipes-ingredients__list li, #mntl-structured-ingredients__list_1-0 li, [class*="ingredient"] li').forEach(li => {
  const txt = li.textContent.trim().replace(/\s+/g, ' ');
  if (txt && txt.length < 200) ingredients.push(txt);
});
return ingredients.length ? ingredients : Array.from(document.querySelectorAll('ul li')).slice(0, 30).map(li => li.textContent.trim().replace(/\s+/g, ' ')).filter(t => t.length > 5 && t.length < 200);
